// Shapes of the files generated by scripts/build-index.mjs (see docs/SITE-SPEC.md).

export type ArtifactType = 'skill' | 'agent';
export type DocKind = 'plugin' | ArtifactType;

export interface Dependency {
  name: string;
  version: string | null;
}

export interface Plugin {
  name: string;
  version: string | null;
  description: string;
  owner: string;
  keywords: string[];
  category: string | null;
  license: string | null;
  compatibility: string | null;
  dependencies: Dependency[];
  dependents: string[];
  components: { skills: string[]; agents: string[]; hooks: number; evals: number };
  install: string;
  readme: string | null;
  changelog: string | null;
  compatibilityDoc: string | null;
  sourcePath: string;
  contextBytes: number;
  searchText: string;
}

export interface Artifact {
  id: string;
  type: ArtifactType;
  name: string;
  plugin: string;
  description: string;
  fields: Record<string, string>;
  body: string | null;
  files: string[];
  sourcePath: string;
  searchText: string;
}

export interface CatalogIndex {
  marketplace: { name: string; owner: string; description: string; repo: string | null };
  generatedAt: string;
  commit: string | null;
  plugins: Plugin[];
  artifacts: Artifact[];
}

export interface Release {
  plugin: string;
  version: string;
  tag: string | null;
  date: string | null;
  commit: string | null;
  untagged: boolean;
  notes: string;
}

export interface ReleasesFile {
  generatedAt: string;
  releases: Release[];
}
